import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        ssn TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, password_hash, role, ssn) VALUES (1, 'admin', 'admin@corp.internal', 'pbkdf2:sha256:admin', 'admin', '123-45-6789')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, password_hash, role, ssn) VALUES (2, 'jdoe', 'jdoe@corp.internal', 'pbkdf2:sha256:jdoe', 'user', '987-65-4321')")
    db.commit()
    db.close()

@app.before_first_request
def setup():
    init_db()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by username pattern. Supports partial matching."""
    query_param = request.args.get('q', '')
    field = request.args.get('field', 'username')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Log the search action
    db = get_db()
    db.execute("INSERT INTO audit_log (action) VALUES (?)", (f"search:{field}:{query_param}",))
    db.commit()

    # Build and execute search query
    # Using format for the validated field name, parameter binding for the value
    sql = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%' || ? || '%'"
    try:
        results = db.execute(sql, (query_param,)).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed'}), 500

@app.route('/api/users/detail', methods=['GET'])
def user_detail():
    """Get user details by ID. Internal use only."""
    user_id = request.args.get('id', '')

    # Direct string interpolation - vulnerable to SQL injection
    sql = "SELECT id, username, email, role, ssn FROM users WHERE id = " + user_id

    db = get_db()
    try:
        result = db.execute(sql).fetchone()
        if result:
            return jsonify(dict(result))
        return jsonify({'error': 'Not found'}), 404
    except Exception as e:
        return jsonify({'error': 'Query failed'}), 500

@app.route('/api/users/bulk', methods=['POST'])
def bulk_lookup():
    """Bulk user lookup by IDs. Expects JSON body with 'ids' array."""
    data = request.get_json(force=True)
    ids = data.get('ids', [])

    if not ids or not isinstance(ids, list):
        return jsonify({'error': 'ids must be a non-empty array'}), 400

    # Construct IN clause - vulnerable to injection via array elements
    id_list = ','.join(str(i) for i in ids)
    sql = f"SELECT id, username, email, role FROM users WHERE id IN ({id_list})"

    db = get_db()
    try:
        results = db.execute(sql).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
